package com.sekai.world.story.model;

public class EventChoice {
    private Long id; private Long eventId; private String code; private String label; private Integer requiredMoodMin; private Integer moodDelta; private String conditionJson; private String effectJson; private Integer sortOrder;
    public EventChoice() {} public EventChoice(Long id,Long eventId,String code,String label,Integer requiredMoodMin,Integer moodDelta,String conditionJson,String effectJson,Integer sortOrder){this.id=id;this.eventId=eventId;this.code=code;this.label=label;this.requiredMoodMin=requiredMoodMin;this.moodDelta=moodDelta;this.conditionJson=conditionJson;this.effectJson=effectJson;this.sortOrder=sortOrder;}
    public Long getId(){return id;} public void setId(Long v){id=v;} public Long getEventId(){return eventId;} public void setEventId(Long v){eventId=v;} public String getCode(){return code;} public void setCode(String v){code=v;} public String getLabel(){return label;} public void setLabel(String v){label=v;} public Integer getRequiredMoodMin(){return requiredMoodMin;} public void setRequiredMoodMin(Integer v){requiredMoodMin=v;} public Integer getMoodDelta(){return moodDelta;} public void setMoodDelta(Integer v){moodDelta=v;} public String getConditionJson(){return conditionJson;} public void setConditionJson(String v){conditionJson=v;} public String getEffectJson(){return effectJson;} public void setEffectJson(String v){effectJson=v;} public Integer getSortOrder(){return sortOrder;} public void setSortOrder(Integer v){sortOrder=v;}
    public Long id(){return id;} public Long eventId(){return eventId;} public String code(){return code;} public String label(){return label;} public Integer requiredMoodMin(){return requiredMoodMin;} public Integer moodDelta(){return moodDelta;} public String conditionJson(){return conditionJson;} public String effectJson(){return effectJson;} public Integer sortOrder(){return sortOrder;}
}
